 const [view,setView]=useState<View>(initialView),[settings,setSettings]=useState(false),[help,setHelp]=useState(false),[join,setJoin]=useState(false),[joinStep,setJoinStep]=useState(0),[demo,setDemo]=useState(false),[user,setUser]=useState<any>(null),[ai,setAi]=useState(false),[online,setOnline]=useState(true),[busy,setBusy]=useState(false),[error,setError]=useState(''),[code,setCode]=useState(''),[nickname,setNickname]=useState(''),[avatar,setAvatar]=useState<Avatar>(defaultAvatar),[activity,setActivity]=useState<Activity>(sample),[session,setSession]=useState<any>(null),[responses,setResponses]=useState<any[]>([]),[station,setStation]=useState(1),[font,setFont]=useState(100),[dark,setDark]=useState(false),[readable,setReadable]=useState(false),[motion,setMotion]=useState(false),[sound,setSound]=useState(false),[resume,setResume]=useState<any>(null);
 useEffect(()=>{api('op=me').then(r=>{setUser(r.user);setAi(r.ai);}).catch(e=>toast.error(e.message));api('op=restore').then(r=>{if(r.activity)setResume(r);}).catch(()=>{});try{const p=JSON.parse(localStorage.getItem('skuad_prefs')||'{}');setFont(p.font||100);setDark(!!p.dark);setReadable(!!p.readable);setMotion(!!p.motion);setSound(!!p.sound);}catch{}const update=()=>setOnline(navigator.onLine);update();window.addEventListener('online',update);window.addEventListener('offline',update);return()=>{window.removeEventListener('online',update);window.removeEventListener('offline',update);};},[]);
 useEffect(()=>{document.documentElement.style.fontSize=`${font}%`;document.documentElement.classList.toggle('dark',dark);localStorage.setItem('skuad_prefs',JSON.stringify({font,dark,readable,motion,sound}));},[font,dark,readable,motion,sound]);
 useEffect(()=>{window.scrollTo({top:0,behavior:'instant'});setError('');},[view]);
