 const navigate=useCallback((target:string)=>{if(target==='home'||target==='teacher'){setView(target as View);return;}throw new Error('Halaman tidak sah.');},[]);
 useEffect(()=>{const ctx=(document as any).modelContext;if(!ctx?.registerTool)return;const lifecycle=new AbortController();try{Promise.resolve(ctx.registerTool({name:'open_skuad_page',description:'Open home or teacher workspace. This does not create or save data.',inputSchema:{type:'object',properties:{page:{type:'string',enum:['home','teacher']}},required:['page'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async(input:any)=>{navigate(input.page);return{page:input.page};}},{signal:lifecycle.signal})).catch(()=>{});}catch{}return()=>lifecycle.abort();},[navigate]);
 const completed=(s:number)=>responses.filter(r=>r.station===s).length>=(s<3?3:1);
 const completedCount=[1,2,3].filter(completed).length;
 function openJoin(isDemo=false){setDemo(isDemo);setJoinStep(isDemo?1:0);setError('');setNickname(isDemo?'Penjelajah':'');setJoin(true);}
 async function enter(){if(!nickname.trim()){setError('Pilih nama panggilan dahulu.');return;}setBusy(true);setError('');try{if(demo){setActivity(structuredClone(sample));setSession({id:'demo',title:sample.title,status:'Aktif',sequential:1});setResponses([]);}else{const r=await api('join',{code,nickname,avatar});setActivity(r.activity);setSession(r.session);setResponses([]);}setJoin(false);setView('map');}catch(e){setError((e as Error).message);}finally{setBusy(false);}}
 async function saveAnswer(s:number,q:number,answer:string,mode:string){let result;if(demo){const question=s===1?activity.questions[q]:s===2?activity.moves[q]:null;const score=question?(answer===question.options[question.answer]?1:0):null;result={saved:true,score,feedback:question?(score?question.feedback:'Usaha yang baik. Dengar semula dan cuba lagi.'):'Terima kasih! Cikgu akan menyemak idea kamu dalam sesi sebenar.'};}else result=await api('answer',{station:s,question:q,answer,mode});setResponses(prev=>[...prev.filter(r=>!(r.station===s&&r.question===q)),{station:s,question:q,answer,mode,score:result.score,review:'Perlu semakan guru'}]);if(sound&&result.score===1){try{const Ctx=window.AudioContext||(window as any).webkitAudioContext;const c=new Ctx();const o=c.createOscillator(),g=c.createGain();o.connect(g);g.connect(c.destination);o.frequency.value=660;g.gain.value=.035;o.start();g.gain.exponentialRampToValueAtTime(.001,c.currentTime+.2);o.stop(c.currentTime+.2);o.onended=()=>c.close();}catch{}}return result;}
 function startStation(s:number){if(session?.sequential&&s>1&&!completed(s-1)){toast('Lengkapkan stesen sebelumnya dahulu.');return;}setStation(s);setView('station');}
 function restore(){if(!resume)return;setDemo(false);setActivity(resume.activity);setSession(resume.session);setNickname(resume.pupil.nickname);setAvatar(resume.pupil.avatar);setResponses(resume.responses);setView('map');}
